command:
set -euo pipefail; env_file="${UA_WHATBOX_ENV_FILE:-${XDG_CONFIG_HOME:-$HOME/.config}/upload-assistant/whatbox.env}"; set -a; source "$env_file"; set +a; export SSHPASS="$UA_WHATBOX_PASSWORD"; sshpass -e ssh -4 -o PubkeyAuthentication=no -o PreferredAuthentications=password -o StrictHostKeyChecking=yes artemisprime@destiny.whatbox.ca bash -s <<'REMOTE'
set -u
podman inspect upload-assistant-wastaken --format 'status={{.State.Status}} pid={{.State.Pid}} image={{.Image}}'
echo health-route:
podman exec upload-assistant-wastaken grep -n -A4 -B2 'Health endpoint can be used' /Upload-Assistant/web_ui/server.py 2>/dev/null || true
echo command:
podman inspect upload-assistant-wastaken --format '{{json .Config.Cmd}}'
echo logs-head:
podman logs --since 20s upload-assistant-wastaken 2>&1 | tail -20 || true
REMOTE
